<template>
  <HeaderEl
    @change-theme="receiveStatus"
    @load="getMode"
    class="header"
    :name="sceneName">
  </HeaderEl>

  <!-- 본문 -->
  <main class="wrap" @onScroll="onScroll">
    <h2 class="mgt8">컴포넌트 모음</h2>
    <ol class="sortUi">
      <li>
        <h3>1. 헤더</h3>
        <div class="affected_scroll">
          <CodeHeader
            @reset-subtitle="receiveLoad"></CodeHeader>
        </div>
      </li>
      <li>
        <h3>2. 테이블</h3>
        <CodeTable></CodeTable>
      </li>
    </ol>
    <section class="uiGuide">
    </section>
  </main>
</template>

<script>
import HeaderEl from './common/Header.vue';
import CodeTable from './common/CodeTable.vue';
import CodeHeader from './common/CodeHeader.vue';

export default {
  // el: '#test',
  name: 'UiCompo',
  components: {
    HeaderEl,
    CodeTable,
    CodeHeader,
  },
  data: () => ({
    sceneName: '컴포넌트',
    header: {
      height: 60,
    },
  }),
  mounted() {
    this.receiveStatus()
    this.getMode()
    this.onScroll()
    this.receiveLoad()

    document.addEventListener('click', this.receiveStatus, true)
    document.addEventListener('load', this.getMode, true)
    window.addEventListener('scroll', this.onScroll, true)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.receiveStatus, true)
    document.removeEventListener('load', this.getMode, true)
    window.removeEventListener('scroll', this.onScroll, true)
  },
  methods: {
    getMode() {
      let thisPage = document.querySelector('#app'),
          modeLight = document.querySelector('.toggle_luminosity img'),
          modeDark = modeLight.nextElementSibling;

      if(thisPage.classList.contains('dark-mode') === true) {
        // console.log('thisPage 다크 모드??:' + thisPage.classList.contains('dark-mode'))
        modeLight.classList.remove('on')
        modeDark.classList.add('on')
      }
    },
    receiveStatus() {
      let detector = document.querySelector('.toggle_luminosity');

      detector.addEventListener('click', (e) => {
        let app = document.querySelector('#app'),
            modeLight = document.querySelector('.toggle_luminosity img'),
            modeDark = modeLight.nextElementSibling;

        console.log(modeLight, modeDark)
        console.log(e.target.classList)
          if(e.target.classList.contains('light') === true) {
            console.log('라이트 모드 감지')
            app.classList.add('dark-mode')
            modeLight.classList.remove('on')
            modeDark.classList.add('on')
          } 
          if(e.target.classList.contains('dark') === true) {
            console.log('다크 모드 감지')
            app.classList.remove('dark-mode')
            modeLight.classList.add('on')
            modeDark.classList.remove('on')
          }
      }, true)
    },
    receiveLoad() {        
      // let subHeader = document.querySelector('.affected_scroll .header'),
      let subTitle = document.querySelector('.affected_scroll h1'),
          toggleBtn = document.querySelector('.affected_scroll .toggle_luminosity');

      subTitle.remove()
      toggleBtn.remove()
      // subHeader.append = '<p>헤더 요소</p>';
    },
    onScroll() {
      // console.log('scrolled');
      // this.windowTop = e.target.scrollTop;

      const header = document.querySelector('.header');
      
      this.windowTop = window.top.scrollY;
      console.log(this.windowTop);

      if(this.windowTop >= this.header.height) {
        header.classList.add('scrolled');
      } else {
        header.classList.remove('scrolled');
      }
    }
  }
}
</script>

