  <HeaderEl
    @change-theme="receiveStatus"
    @load="getMode"
    class="header"
    :name="sceneName">
  </HeaderEl>

  <!-- 본문 -->
  <main class="wrap" @onScroll="onScroll">
    <h2>
      <label><small>1</small></label>
      <span>폰트 스타일</span>
    </h2>
    <VforRepeat
      :items="fontgroup01"></VforRepeat>
    <VforRepeat 
      :isItNext="{ nextList: isList }" 
      :items="fontgroup02"></VforRepeat>

    
    <h2>
      <label><small>2</small></label>
      <span>버튼 스타일</span>
    </h2>  
    <VforRepeat
      class="ui_btnscale"
      :items="btnscalegroup"></VforRepeat>
    <VforRepeat
      class="ui_btnshadow"
      :items="btnshadowgroup"></VforRepeat>
    <VforRepeat
      class="ui_btnicotouch"
      :isItNext="{ nextList: isList }"
      :items="btnicotouchgroup"></VforRepeat>

    <!-- <h2>
      <label><small>3</small></label>
