<script>
import HeaderEl from './common/Header.vue';
import CodeFrag from './common/CodeFrag.vue';

export default {
  name: 'SourceTree',
  components: {
    HeaderEl,
    CodeFrag,
  },
  data: () => ({
    sceneName: '버전 관리',
    window: {
      width: 0,
      height: 0,
    },
    sortCode: true,
    gitMenuBtns: [
      {
        purpose: '목적',
        className: 'on',
      },
      {purpose: '커밋'},
      {purpose: '코멘트'},
      {purpose: '브랜치'},
    ],
    gitMenuThumbs: [
      {
        src: require('@/assets/images/git_purpose.png'),
        srcInfo: '깃 사용 목적을 나타내는 사례 이미지', 
        className: 'on',
      },
      {
        src: require('@/assets/images/git_commit.png'),
        srcInfo: '깃 커밋 이력을 나타내는 사례 이미지',   
      },
      {
        src: require('@/assets/images/git_comment.png'),
        srcInfo: '깃 코멘트 내역을 안내하는 사례 이미지',   
      },
      {
        src: require('@/assets/images/git_branch.png'),
        srcInfo: '깃 브랜치 구분을 안내하는 사례 이미지',   
      },
    ],
    diagramInfo: [
      { useflow: '디렉토리'}, 
      { useflow: '스테이징'}, 
      { useflow: '브랜치 선택'}, 
      { useflow: '커밋'}
    ],
    commandsInGit: [
      {
        command1: 'branch',
        command2: '"branchName"',
        isOption: true,
      },
      {
        command1: 'checkout',
        command2: '"branchName"',
        isOption: true,
      },
      {
        command1: 'status',
        isOption: false,
      },
      {
        command1: 'log',
        isOption: false,
      },
      {
        command1: 'add',
        command2: '.',
        isOption: false,
      },
      {
        command1: 'add',
        command2: '-i',
        isOption: false,
      },
      {
        command1: 'rm',
        command2: '-r',
        command3: '-—cached',
        isOption: false,
      },
      {
        command1: 'commit',
        command2: '-m',
        command3: '"comment"',
        isOption: true,
      },
      {
        command1: 'commit',
        command2: '-a-m',
        command3: '"comment"',
        isOption: true,
      },
    ],
  }),
  mounted() {
    this.receiveStatus()
    this.getMode()

    this.showThumbs()
    this.onScroll()

    document.addEventListener('click', this.receiveStatus, true)
    document.addEventListener('load', this.getMode, true)
    window.addEventListener("scroll", this.onScroll, true)
  },
  beforeUnmount() {
    document.removeEventListener('click', this.receiveStatus, true)
    document.removeEventListener('load', this.getMode, true)
    window.removeEventListener("scroll", this.onScroll, true)
  },
  methods: {
    getMode() {
      let thisPage = document.querySelector('#app'),
          modeLight = document.querySelector('.toggle_luminosity img'),
          modeDark = modeLight.nextElementSibling;

      if(thisPage.classList.contains('dark-mode') === true) {
        // console.log('thisPage 다크 모드??:' + thisPage.classList.contains('dark-mode'))
        modeLight.classList.remove('on')
        modeDark.classList.add('on')
      }
    },
    receiveStatus() {
      let detector = document.querySelector('.toggle_luminosity');

      detector.addEventListener('click', (e) => {
        let app = document.querySelector('#app'),
            modeLight = document.querySelector('.toggle_luminosity img'),
            modeDark = modeLight.nextElementSibling;

        // console.log(modeLight, modeDark)
        // console.log(e.target.classList)
          if(e.target.classList.contains('light') === true) {
            // console.log('라이트 모드 감지')
            app.classList.add('dark-mode')
            modeLight.classList.remove('on')
            modeDark.classList.add('on')
          } 
          if(e.target.classList.contains('dark') === true) {
            // console.log('다크 모드 감지')
            app.classList.remove('dark-mode')
            modeLight.classList.add('on')
            modeDark.classList.remove('on')
          }
      }, true)
    },
    showThumbs() {
      const tabBtngroup = document.querySelector('.btngroup'),
            sortingBtns = tabBtngroup.querySelectorAll('li'),
            sortingThumbs = document.querySelectorAll('.thumbs li');
      console.log(sortingThumbs);
      
      for(let i = 0; i < sortingBtns.length; i++) {
        sortingBtns[i].addEventListener('click', function(){
          sortingBtns[i].classList.add('on');
          sortingThumbs[i].classList.add('on');
          for(let j = 0; j < sortingBtns.length; j++) {
            /* 인덱스가 서로 다르면 on 클레스 제거 */  
            if(i !== j) {
              sortingBtns[j].classList.remove('on');
              sortingThumbs[j].classList.remove('on');
            }
          }
        })
      }
    },
    onScroll() {
      const wrap = document.querySelector('.wrap'),
            header = document.querySelector('.header');

      this.windowTop = window.top.scrollY;
      this.scrolledTop = wrap.scrollTop;
      this.window.height = window.innerHeight;
      wrap.height = this.window.height - 52;    // header.innerHeight JS표현식 나중에 알아보기
      wrap.height = wrap.height * 5;
      console.log(this.windowTop);
      console.log(wrap.height);

      if(this.scrolledTop > 0) {
        header.classList.add('scrolled');
        console.log(wrap.height);
      } else {
        header.classList.remove('scrolled');
      }
    }
  }
}
</script>

